<?php
declare(strict_types=1);namespace Vendi\Inventory;use PDO;use RuntimeException;
final class TransferService{public function __construct(private PDO $db){}
 public function create(int $businessId,int $from,int $to,int $userId,array $items,?string $notes=null):int{if($from===$to)throw new RuntimeException('Origen y destino deben ser distintos.');if(!$items)throw new RuntimeException('Agrega mercancía.');$this->db->beginTransaction();try{$q=$this->db->prepare("INSERT INTO stock_transfers(business_id,from_branch_id,to_branch_id,status,created_by,notes,created_at) VALUES(?,?,?,'draft',?,?,NOW())");$q->execute([$businessId,$from,$to,$userId,$notes]);$id=(int)$this->db->lastInsertId();foreach($items as$x){$qty=(float)$x['quantity_base'];if($qty<=0)continue;$this->db->prepare("INSERT INTO stock_transfer_items(transfer_id,product_id,presentation_id,qty_presentation,qty_base,lot_id,serial_id) VALUES(?,?,?,?,?,?,?)")->execute([$id,(int)$x['product_id'],$x['presentation_id']??null,$x['quantity_presentation']??$qty,$qty,$x['lot_id']??null,$x['serial_id']??null]);}$this->db->commit();return$id;}catch(\Throwable$e){$this->db->rollBack();throw$e;}}
 public function send(int $businessId,int $id,int $userId):void{$this->db->beginTransaction();try{$t=$this->lock($businessId,$id);if($t['status']!=='draft')throw new RuntimeException('La transferencia ya fue procesada.');foreach($this->items($id) as$x){$q=$this->db->prepare("SELECT quantity FROM inventory WHERE branch_id=? AND product_id=? FOR UPDATE");$q->execute([$t['from_branch_id'],$x['product_id']]);if((float)($q->fetchColumn()?:0)<(float)$x['qty_base'])throw new RuntimeException('Existencia insuficiente para enviar.');$this->db->prepare("UPDATE inventory SET quantity=quantity-? WHERE branch_id=? AND product_id=?")->execute([$x['qty_base'],$t['from_branch_id'],$x['product_id']]);$this->move($businessId,(int)$t['from_branch_id'],(int)$x['product_id'],-(float)$x['qty_base'],$id,$userId);if($x['serial_id'])$this->db->prepare("UPDATE inventory_serials SET status='transit' WHERE id=? AND branch_id=? AND status='available'")->execute([$x['serial_id'],$t['from_branch_id']]);}$this->db->prepare("UPDATE stock_transfers SET status='sent' WHERE id=?")->execute([$id]);$this->db->commit();}catch(\Throwable$e){$this->db->rollBack();throw$e;}}
 public function receive(int $businessId,int $id,int $userId):void{$this->db->beginTransaction();try{$t=$this->lock($businessId,$id);if($t['status']!=='sent')throw new RuntimeException('La transferencia no está en tránsito.');foreach($this->items($id) as$x){$this->db->prepare("INSERT INTO inventory(branch_id,product_id,quantity) VALUES(?,?,?) ON DUPLICATE KEY UPDATE quantity=quantity+VALUES(quantity)")->execute([$t['to_branch_id'],$x['product_id'],$x['qty_base']]);$this->move($businessId,(int)$t['to_branch_id'],(int)$x['product_id'],(float)$x['qty_base'],$id,$userId);if($x['serial_id'])$this->db->prepare("UPDATE inventory_serials SET status='available',branch_id=? WHERE id=? AND status='transit'")->execute([$t['to_branch_id'],$x['serial_id']]);}$this->db->prepare("UPDATE stock_transfers SET status='received' WHERE id=?")->execute([$id]);$this->db->commit();}catch(\Throwable$e){$this->db->rollBack();throw$e;}}
 private function lock(int$b,int$id):array{$q=$this->db->prepare("SELECT * FROM stock_transfers WHERE id=? AND business_id=? FOR UPDATE");$q->execute([$id,$b]);$r=$q->fetch();if(!$r)throw new RuntimeException('Transferencia no encontrada.');return$r;}private function items(int$id):array{$q=$this->db->prepare("SELECT * FROM stock_transfer_items WHERE transfer_id=?");$q->execute([$id]);return$q->fetchAll();}private function move(int$b,int$branch,int$p,float$q,int$r,int$u):void{$s=$this->db->prepare("INSERT INTO stock_movements(business_id,branch_id,product_id,type,quantity,reference_type,reference_id,user_id,created_at) VALUES(?,?,?,'transfer',?,'stock_transfer',?,?,NOW())");$s->execute([$b,$branch,$p,$q,$r,$u]);}}
